{
  "name": "relayapi-rate-limiter",
  "version": "1.0.0",
  "description": "Distributed per-customer rate limiter for RelayAPI using sliding window log",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "dev": "node src/server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "ioredis": "^5.3.2"
  }
}

/**
 * Customer configuration for RelayAPI rate limiter.
 *
 * Each customer has:
 *   - customerId: unique identifier (comes from X-Customer-Id header)
 *   - tier: pricing tier name
 *   - baseRpm: default requests-per-minute limit
 *   - scheduleOverrides: optional array of time-based RPM overrides
 *
 * Schedule overrides allow raising (or lowering) a customer's RPM
 * during specific time windows. This is a generic, auditable feature —
 * not a customer-specific hack. Any Enterprise customer can have overrides.
 *
 * Overrides are checked in order. The first matching window wins.
 * If no override matches, baseRpm is used.
 */

const customers = {
  "northwind": {
    customerId: "northwind",
    tier: "enterprise",
    baseRpm: 300,
    scheduleOverrides: [
      {
        windowStart: "02:00",   // UTC
        windowEnd: "04:00",     // UTC
        rpm: 1500,
        reason: "Contracted nightly batch window — approved by sales",
        approvedBy: "priya@relayapi.com"
      }
    ]
  },

  "acme-corp": {
    customerId: "acme-corp",
    tier: "growth",
    baseRpm: 300,
    scheduleOverrides: []
  },

  "small-biz": {
    customerId: "small-biz",
    tier: "starter",
    baseRpm: 60,
    scheduleOverrides: []
  }
};

// Default config for unknown customers (safety net)
const defaultCustomerConfig = {
  tier: "starter",
  baseRpm: 60,
  scheduleOverrides: []
};

/**
 * Get the current effective RPM for a customer.
 *
 * Checks if any schedule override is active right now.
 * If yes, returns the override RPM.
 * If no, returns the base RPM.
 *
 * @param {string} customerId
 * @returns {{ rpm: number, isOverride: boolean, reason: string | null }}
 */
function getEffectiveRpm(customerId) {
  const customer = customers[customerId];

  if (!customer) {
    return {
      rpm: defaultCustomerConfig.baseRpm,
      isOverride: false,
      reason: null
    };
  }

  // Check schedule overrides
  const now = new Date();
  const currentUtcHours = now.getUTCHours();
  const currentUtcMinutes = now.getUTCMinutes();
  const currentTimeMinutes = currentUtcHours * 60 + currentUtcMinutes;

  for (const override of customer.scheduleOverrides) {
    const [startHour, startMin] = override.windowStart.split(":").map(Number);
    const [endHour, endMin] = override.windowEnd.split(":").map(Number);

    const startMinutes = startHour * 60 + startMin;
    const endMinutes = endHour * 60 + endMin;

    // Check if current time falls within the override window
    let isInWindow = false;

    if (startMinutes < endMinutes) {
      // Normal window (e.g., 02:00 to 04:00)
      isInWindow = currentTimeMinutes >= startMinutes && currentTimeMinutes < endMinutes;
    } else {
      // Overnight window (e.g., 23:00 to 03:00)
      isInWindow = currentTimeMinutes >= startMinutes || currentTimeMinutes < endMinutes;
    }

    if (isInWindow) {
      return {
        rpm: override.rpm,
        isOverride: true,
        reason: override.reason
      };
    }
  }

  // No override matched — use base RPM
  return {
    rpm: customer.baseRpm,
    isOverride: false,
    reason: null
  };
}

/**
 * Get the full customer config (for audit/debug endpoints).
 *
 * @param {string} customerId
 * @returns {object}
 */
function getCustomerConfig(customerId) {
  return customers[customerId] || { customerId, ...defaultCustomerConfig };
}

module.exports = {
  customers,
  defaultCustomerConfig,
  getEffectiveRpm,
  getCustomerConfig
};

const Redis = require("ioredis");

/**
 * Redis client setup for the rate limiter.
 *
 * Connects to Redis using environment variables.
 * Tracks connection status so the rate limiter can
 * fall back to in-memory counting if Redis is down.
 */

let redisClient = null;
let isRedisAvailable = false;

function createRedisClient() {
  const redisHost = process.env.REDIS_HOST || "localhost";
  const redisPort = parseInt(process.env.REDIS_PORT || "6379", 10);

  redisClient = new Redis({
    host: redisHost,
    port: redisPort,
    // Retry connecting every 2 seconds if disconnected
    retryStrategy(times) {
      const delay = Math.min(times * 500, 2000);
      return delay;
    },
    // Don't buffer commands when disconnected — fail fast
    enableOfflineQueue: false,
    // Connection timeout
    connectTimeout: 5000
  });

  redisClient.on("connect", () => {
    isRedisAvailable = true;
    console.log(`[Redis] Connected to ${redisHost}:${redisPort}`);
  });

  redisClient.on("ready", () => {
    isRedisAvailable = true;
    console.log("[Redis] Ready to accept commands");
  });

  redisClient.on("error", (err) => {
    isRedisAvailable = false;
    console.error("[Redis] Connection error:", err.message);
  });

  redisClient.on("close", () => {
    isRedisAvailable = false;
    console.log("[Redis] Connection closed");
  });

  return redisClient;
}

/**
 * Get the Redis client instance.
 * Creates one if it doesn't exist yet.
 */
function getRedisClient() {
  if (!redisClient) {
    createRedisClient();
  }
  return redisClient;
}

/**
 * Check if Redis is currently connected and available.
 */
function getRedisStatus() {
  return isRedisAvailable;
}

/**
 * Gracefully close the Redis connection.
 */
async function closeRedis() {
  if (redisClient) {
    await redisClient.quit();
    redisClient = null;
    isRedisAvailable = false;
    console.log("[Redis] Disconnected gracefully");
  }
}

module.exports = {
  getRedisClient,
  getRedisStatus,
  closeRedis
};

const { getRedisClient, getRedisStatus } = require("../lib/redis");
const { getEffectiveRpm } = require("../config/customers");

/**
 * Sliding Window Log Rate Limiter
 *
 * How it works:
 * - Each customer gets a Redis sorted set: "ratelimit:{customerId}"
 * - Each ALLOWED request adds an entry with score = timestamp in microseconds
 * - Members are unique strings (timestamp + random suffix) to avoid collisions
 * - On each request, we:
 *   1. Remove all entries older than 60 seconds (outside the window)
 *   2. Count remaining entries
 *   3. If count < RPM limit, add a new entry and ALLOW
 *   4. If count >= RPM limit, REJECT (do NOT add the entry)
 * - All of this happens in a single atomic Lua script
 * - We use Redis TIME for the clock (not the app server's clock)
 *   to avoid clock drift between nodes
 *
 * IMPORTANT: Rejected requests are NOT counted.
 * Northwind retries aggressively on 429 — counting rejections
 * would create a death spiral where retries eat the budget.
 *
 * Fallback (Redis unavailable):
 * - Each node enforces RPM / 3 using an in-memory sliding window
 * - With 3 nodes and round-robin LB, this approximates the global limit
 * - Errs on the side of over-rejecting (CTO's preference)
 */

// ============================================================
// Lua script for atomic sliding window log in Redis
// ============================================================
//
// KEYS[1] = sorted set key for this customer
// ARGV[1] = window size in microseconds (60 seconds = 60000000)
// ARGV[2] = max allowed requests (RPM limit)
// ARGV[3] = unique member string for this request
//
// Returns: [allowed (0 or 1), currentCount, remainingRequests, retryAfterMs]

const LUA_SLIDING_WINDOW_LOG = `
-- Get the current time from Redis server (not app server)
-- redis.call('TIME') returns {seconds, microseconds}
local redisTime = redis.call('TIME')
local nowMicro = tonumber(redisTime[1]) * 1000000 + tonumber(redisTime[2])

local key = KEYS[1]
local windowMicro = tonumber(ARGV[1])
local maxRequests = tonumber(ARGV[2])
local member = ARGV[3]

-- Calculate the start of the sliding window
local windowStart = nowMicro - windowMicro

-- Step 1: Remove all entries outside the window (older than 60s ago)
redis.call('ZREMRANGEBYSCORE', key, '-inf', windowStart)

-- Step 2: Count how many requests are in the current window
local currentCount = redis.call('ZCARD', key)

-- Step 3: Decide — allow or reject
if currentCount < maxRequests then
    -- ALLOW: Add this request to the sorted set
    redis.call('ZADD', key, nowMicro, member)

    -- Set TTL on the key so it auto-cleans (window + small buffer)
    redis.call('PEXPIRE', key, math.ceil(windowMicro / 1000) + 1000)

    local remaining = maxRequests - currentCount - 1
    return {1, currentCount + 1, remaining, 0}
else
    -- REJECT: Do NOT add to the set (rejected requests are not counted)

    -- Calculate retry-after: time until the oldest entry expires
    local oldestEntries = redis.call('ZRANGE', key, 0, 0, 'WITHSCORES')
    local retryAfterMs = 0
    if #oldestEntries >= 2 then
        local oldestScore = tonumber(oldestEntries[2])
        -- The oldest entry will expire at oldestScore + windowMicro
        local expiresAtMicro = oldestScore + windowMicro
        retryAfterMs = math.ceil((expiresAtMicro - nowMicro) / 1000)
        if retryAfterMs < 0 then
            retryAfterMs = 0
        end
    end

    local remaining = 0
    return {0, currentCount, remaining, retryAfterMs}
end
`;

// ============================================================
// In-memory fallback (used when Redis is unavailable)
// ============================================================

// Map of customerId -> array of timestamps (in milliseconds)
const inMemoryWindows = new Map();

// How many nodes we assume are running (for dividing the RPM)
const TOTAL_NODES = parseInt(process.env.TOTAL_NODES || "3", 10);

/**
 * In-memory sliding window log for a single node.
 * Enforces RPM / TOTAL_NODES to approximate the global limit.
 *
 * @param {string} customerId
 * @param {number} rpm - full RPM limit for the customer
 * @returns {{ allowed: boolean, currentCount: number, remaining: number, retryAfterMs: number }}
 */
function checkInMemoryLimit(customerId, rpm) {
  const now = Date.now();
  const windowMs = 60 * 1000; // 60 seconds
  const windowStart = now - windowMs;

  // Per-node limit: divide by number of nodes
  const perNodeLimit = Math.floor(rpm / TOTAL_NODES);

  // Get or create the request log for this customer
  if (!inMemoryWindows.has(customerId)) {
    inMemoryWindows.set(customerId, []);
  }

  const requestLog = inMemoryWindows.get(customerId);

  // Remove entries outside the window
  while (requestLog.length > 0 && requestLog[0] <= windowStart) {
    requestLog.shift();
  }

  const currentCount = requestLog.length;

  if (currentCount < perNodeLimit) {
    // ALLOW — add timestamp
    requestLog.push(now);
    return {
      allowed: true,
      currentCount: currentCount + 1,
      remaining: perNodeLimit - currentCount - 1,
      retryAfterMs: 0
    };
  } else {
    // REJECT — do NOT add timestamp
    let retryAfterMs = 0;
    if (requestLog.length > 0) {
      // Time until the oldest entry exits the window
      retryAfterMs = Math.max(0, (requestLog[0] + windowMs) - now);
    }
    return {
      allowed: false,
      currentCount: currentCount,
      remaining: 0,
      retryAfterMs: Math.ceil(retryAfterMs)
    };
  }
}

// ============================================================
// Rate limiter middleware
// ============================================================

/**
 * Express middleware that enforces per-customer rate limits.
 *
 * Reads the customer ID from the X-Customer-Id header.
 * Looks up their effective RPM (including schedule overrides).
 * Uses Redis sliding window log if available, else in-memory fallback.
 *
 * Response headers on every request:
 *   X-RateLimit-Limit: the current RPM limit
 *   X-RateLimit-Remaining: requests left in this window
 *   X-RateLimit-Source: "redis" or "in-memory" (for debugging)
 *
 * On rejection (429):
 *   Retry-After: seconds until a slot opens up
 */
function rateLimiterMiddleware(req, res, next) {
  const customerId = req.headers["x-customer-id"];

  // No customer ID = reject immediately
  if (!customerId) {
    return res.status(400).json({
      error: "Missing X-Customer-Id header"
    });
  }

  // Get the effective RPM for this customer right now
  const { rpm, isOverride, reason } = getEffectiveRpm(customerId);

  // Check if Redis is available
  if (getRedisStatus()) {
    // ---- Redis path: distributed sliding window log ----
    checkRedisLimit(customerId, rpm)
      .then((result) => {
        setRateLimitHeaders(res, rpm, result.remaining, "redis");

        if (result.allowed) {
          // Request is allowed — continue to the route handler
          next();
        } else {
          // Request is rejected — return 429
          const retryAfterSeconds = Math.ceil(result.retryAfterMs / 1000);
          res.set("Retry-After", String(Math.max(1, retryAfterSeconds)));
          res.status(429).json({
            error: "Too Many Requests",
            message: `Rate limit exceeded. Your limit is ${rpm} requests per minute.`,
            retryAfterMs: result.retryAfterMs
          });
        }
      })
      .catch((err) => {
        // Redis command failed — fall back to in-memory
        console.error("[RateLimiter] Redis error, falling back to in-memory:", err.message);
        handleInMemoryFallback(customerId, rpm, res, next);
      });
  } else {
    // ---- In-memory fallback path ----
    handleInMemoryFallback(customerId, rpm, res, next);
  }
}

/**
 * Check rate limit using Redis sliding window log.
 *
 * @param {string} customerId
 * @param {number} rpm
 * @returns {Promise<{ allowed: boolean, currentCount: number, remaining: number, retryAfterMs: number }>}
 */
async function checkRedisLimit(customerId, rpm) {
  const redis = getRedisClient();

  const key = `ratelimit:${customerId}`;
  const windowMicro = 60 * 1000000; // 60 seconds in microseconds

  // Create a unique member for this request
  // Using Redis TIME + random suffix to avoid collisions
  const uniqueMember = `${Date.now()}-${Math.random().toString(36).substring(2, 10)}`;

  const result = await redis.eval(
    LUA_SLIDING_WINDOW_LOG,
    1,           // number of keys
    key,         // KEYS[1]
    windowMicro, // ARGV[1]
    rpm,         // ARGV[2]
    uniqueMember // ARGV[3]
  );

  // Lua returns an array: [allowed, currentCount, remaining, retryAfterMs]
  return {
    allowed: result[0] === 1,
    currentCount: result[1],
    remaining: result[2],
    retryAfterMs: result[3]
  };
}

/**
 * Handle rate limiting using in-memory fallback.
 * Used when Redis is unavailable.
 */
function handleInMemoryFallback(customerId, rpm, res, next) {
  const result = checkInMemoryLimit(customerId, rpm);

  const perNodeLimit = Math.floor(rpm / TOTAL_NODES);
  setRateLimitHeaders(res, perNodeLimit, result.remaining, "in-memory");

  if (result.allowed) {
    next();
  } else {
    const retryAfterSeconds = Math.ceil(result.retryAfterMs / 1000);
    res.set("Retry-After", String(Math.max(1, retryAfterSeconds)));
    res.status(429).json({
      error: "Too Many Requests",
      message: `Rate limit exceeded. Per-node limit is ${perNodeLimit} requests per minute (Redis unavailable, degraded mode).`,
      retryAfterMs: result.retryAfterMs
    });
  }
}

/**
 * Set standard rate limit response headers.
 */
function setRateLimitHeaders(res, limit, remaining, source) {
  res.set("X-RateLimit-Limit", String(limit));
  res.set("X-RateLimit-Remaining", String(Math.max(0, remaining)));
  res.set("X-RateLimit-Source", source);
}

module.exports = { rateLimiterMiddleware };

const express = require("express");
const { rateLimiterMiddleware } = require("./middleware/rateLimiter");
const { getRedisClient, getRedisStatus, closeRedis } = require("./lib/redis");
const { getEffectiveRpm, getCustomerConfig } = require("./config/customers");

/**
 * RelayAPI Rate Limiter Service
 *
 * A stateless Express app that enforces per-customer rate limits
 * using a distributed sliding window log in Redis.
 *
 * Each instance is meant to run behind a load balancer.
 * Multiple instances share state via Redis.
 */

const app = express();

// Port and node ID from environment (each Docker container gets its own)
const PORT = parseInt(process.env.PORT || "3000", 10);
const NODE_ID = process.env.NODE_ID || "node-1";

// ============================================================
// Middleware
// ============================================================

// Parse JSON bodies (for any POST endpoints if needed)
app.use(express.json());

// Log every incoming request with the node ID
app.use((req, res, next) => {
  console.log(`[${NODE_ID}] ${req.method} ${req.path} | Customer: ${req.headers["x-customer-id"] || "none"}`);
  next();
});

// ============================================================
// Routes
// ============================================================

/**
 * Health check — does NOT go through rate limiter.
 * Used by load balancer to check if the node is alive.
 */
app.get("/health", (req, res) => {
  res.json({
    status: "ok",
    nodeId: NODE_ID,
    redis: getRedisStatus() ? "connected" : "disconnected",
    timestamp: new Date().toISOString()
  });
});

/**
 * GET /api/v1/resource
 *
 * A mock API endpoint that goes through the rate limiter.
 * This simulates any real API endpoint that Northwind or
 * other customers would call.
 */
app.get("/api/v1/resource", rateLimiterMiddleware, (req, res) => {
  const customerId = req.headers["x-customer-id"];
  const { rpm, isOverride, reason } = getEffectiveRpm(customerId);

  res.json({
    message: "Request successful",
    data: {
      nodeId: NODE_ID,
      customerId: customerId,
      effectiveRpm: rpm,
      isScheduleOverride: isOverride,
      timestamp: new Date().toISOString()
    }
  });
});

/**
 * GET /api/v1/audit/customer/:customerId
 *
 * Audit endpoint — shows the full config and current effective
 * RPM for a customer. Does NOT go through rate limiter.
 *
 * This satisfies the CTO's auditability requirement:
 * enterprise prospects can see exactly how their limits work.
 */
app.get("/api/v1/audit/customer/:customerId", (req, res) => {
  const customerId = req.params.customerId;
  const config = getCustomerConfig(customerId);
  const effective = getEffectiveRpm(customerId);

  res.json({
    nodeId: NODE_ID,
    customer: config,
    currentEffective: {
      rpm: effective.rpm,
      isScheduleOverride: effective.isOverride,
      overrideReason: effective.reason,
      checkedAt: new Date().toISOString()
    },
    countingMethod: "Sliding window log (60-second window). Each allowed request is recorded with a microsecond timestamp. Rejected requests are not counted."
  });
});

// ============================================================
// Server startup
// ============================================================

// Initialize Redis connection on startup
getRedisClient();

const server = app.listen(PORT, () => {
  console.log(`[${NODE_ID}] RelayAPI rate limiter running on port ${PORT}`);
  console.log(`[${NODE_ID}] Redis status: ${getRedisStatus() ? "connected" : "connecting..."}`);
});

// ============================================================
// Graceful shutdown
// ============================================================

async function shutdown(signal) {
  console.log(`[${NODE_ID}] Received ${signal}, shutting down gracefully...`);

  server.close(async () => {
    await closeRedis();
    console.log(`[${NODE_ID}] Shutdown complete`);
    process.exit(0);
  });

  // Force exit after 5 seconds if graceful shutdown hangs
  setTimeout(() => {
    console.error(`[${NODE_ID}] Forced shutdown after timeout`);
    process.exit(1);
  }, 5000);
}

process.on("SIGTERM", () => shutdown("SIGTERM"));
process.on("SIGINT", () => shutdown("SIGINT"));

module.exports = app;

# Nginx load balancer config
# Round-robin across the 3 app nodes (no sticky sessions)

upstream relayapi {
    server app-node-1:3000;
    server app-node-2:3000;
    server app-node-3:3000;
}

server {
    listen 80;

    location / {
        proxy_pass http://relayapi;

        # Pass through all headers (including X-Customer-Id)
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        # Pass through rate limit response headers
        proxy_pass_header X-RateLimit-Limit;
        proxy_pass_header X-RateLimit-Remaining;
        proxy_pass_header X-RateLimit-Source;
        proxy_pass_header Retry-After;
    }
}

