/**
 * API helper for the dashboard.
 * All requests go through the Vite proxy to http://localhost:8080.
 */

const BASE = "";  // Vite proxy handles /api -> localhost:8080

/**
 * Make a request to the rate limiter service.
 */
export async function apiRequest(method, path, body = null, headers = {}) {
  const options = {
    method,
    headers: {
      "Content-Type": "application/json",
      ...headers
    }
  };

  if (body) {
    options.body = JSON.stringify(body);
  }

  const response = await fetch(`${BASE}${path}`, options);

  const data = await response.json().catch(() => null);

  return {
    statusCode: response.status,
    headers: Object.fromEntries(response.headers.entries()),
    body: data
  };
}

/**
 * Send a burst of N requests for a given customer.
 * Fires all requests in parallel and returns results.
 */
export async function sendBurst(customerId, count) {
  const promises = [];
  for (let i = 0; i < count; i++) {
    promises.push(
      apiRequest("GET", "/api/v1/resource", null, { "X-Customer-Id": customerId })
    );
  }
  return Promise.all(promises);
}

/**
 * Check service health.
 */
export async function checkHealth() {
  return apiRequest("GET", "/health");
}

/**
 * Get audit info for a customer.
 */
export async function getAudit(customerId) {
  return apiRequest("GET", `/api/v1/audit/customer/${customerId}`);
}

/**
 * Set simulated time on all nodes (send 6 times for round-robin coverage).
 */
export async function setSimulatedTime(isoTime) {
  const promises = [];
  for (let i = 0; i < 6; i++) {
    promises.push(apiRequest("POST", "/api/v1/test/set-time", { time: isoTime }));
  }
  return Promise.all(promises);
}

/**
 * Reset simulated time on all nodes.
 */
export async function resetSimulatedTime() {
  const promises = [];
  for (let i = 0; i < 6; i++) {
    promises.push(apiRequest("POST", "/api/v1/test/reset-time"));
  }
  return Promise.all(promises);
}

import { useState } from "react";
import { sendBurst, checkHealth, getAudit, setSimulatedTime, resetSimulatedTime } from "../api";

/**
 * Harness Tests Panel
 *
 * Runs all 10 harness test scenarios with live status updates.
 * Each test shows PASS/FAIL/RUNNING status in a table.
 */

const TEST_DEFINITIONS = [
  {
    id: 1,
    name: "Basic enforcement (60 RPM, send 75)",
    description: "Sends 75 requests for a 60 RPM customer. Expects 60 allowed, 15 rejected."
  },
  {
    id: 2,
    name: "Multi-customer isolation",
    description: "Two customers on same tier. Flooding one should not affect the other."
  },
  {
    id: 3,
    name: "Northwind batch window (1500 RPM)",
    description: "Simulates 02:30 UTC. Northwind should get 1500 RPM override."
  },
  {
    id: 4,
    name: "Distributed correctness (3 nodes)",
    description: "Total allowed across all nodes should equal RPM, not RPM × 3."
  },
  {
    id: 5,
    name: "Boundary precision (RPM then RPM+1)",
    description: "Exactly 60 requests pass, then request #61 gets rejected."
  },
  {
    id: 6,
    name: "Retry-After header validation",
    description: "Verify 429 response includes correct Retry-After and rate limit headers."
  },
  {
    id: 7,
    name: "Northwind batch window end (1500→300)",
    description: "RPM drops from 1500 to 300 when batch window ends at 04:00 UTC."
  },
  {
    id: 8,
    name: "Redis source verification",
    description: "X-RateLimit-Source header should say 'redis' when Redis is connected."
  }
];

export default function HarnessTests() {
  const [results, setResults] = useState([]);
  const [isRunning, setIsRunning] = useState(false);
  const [currentTest, setCurrentTest] = useState(null);
  const [logs, setLogs] = useState([]);

  function addLog(message, type = "info") {
    setLogs((prev) => [...prev, { message, type, time: new Date().toLocaleTimeString() }]);
  }

  function updateResult(id, status, detail) {
    setResults((prev) => {
      const existing = prev.find((r) => r.id === id);
      if (existing) {
        return prev.map((r) => (r.id === id ? { ...r, status, detail } : r));
      }
      return [...prev, { id, status, detail }];
    });
  }

  async function runAllTests() {
    setIsRunning(true);
    setResults([]);
    setLogs([]);

    // Initialize all tests as pending
    TEST_DEFINITIONS.forEach((t) => {
      updateResult(t.id, "pending", "Waiting...");
    });

    try {
      // Check health first
      addLog("Checking service health...");
      const health = await checkHealth();
      if (health.statusCode !== 200) {
        addLog("Service is not healthy! Aborting.", "error");
        setIsRunning(false);
        return;
      }
      addLog(`Service healthy — ${health.body.nodeId}, Redis: ${health.body.redis}`, "success");

      // Reset any simulated time
      await resetSimulatedTime();

      // Test 1: Basic enforcement
      await runTest1();
      // Test 2: Customer isolation
      await runTest2();
      // Test 3: Northwind batch window
      await runTest3();
      // Test 4: Distributed correctness
      await runTest4();
      // Test 5: Boundary precision
      await runTest5();
      // Test 6: Retry-After
      await runTest6();
      // Test 7: Batch window end
      await runTest7();
      // Test 8: Redis source
      await runTest8();

      addLog("All tests complete!", "success");
    } catch (err) {
      addLog(`Harness error: ${err.message}`, "error");
    }

    setIsRunning(false);
    setCurrentTest(null);
  }

  async function runTest1() {
    setCurrentTest(1);
    updateResult(1, "running", "Sending 75 requests...");
    addLog("Test 1: Sending 75 requests for small-biz (60 RPM)...");

    const customerId = "harness-test1-" + Date.now();
    // We need to use a customer with 60 RPM — unknown customers default to 60 RPM
    const responses = await sendBurst(customerId, 75);
    const allowed = responses.filter((r) => r.statusCode === 200).length;
    const rejected = responses.filter((r) => r.statusCode === 429).length;

    const passed = allowed === 60 && rejected === 15;
    const detail = `Allowed: ${allowed}/60, Rejected: ${rejected}/15`;
    updateResult(1, passed ? "pass" : "fail", detail);
    addLog(`Test 1: ${detail}`, passed ? "success" : "error");
  }

  async function runTest2() {
    setCurrentTest(2);
    updateResult(2, "running", "Flooding customer A...");
    addLog("Test 2: Multi-customer isolation...");

    const idA = "harness-iso-a-" + Date.now();
    const idB = "harness-iso-b-" + Date.now();

    // Flood customer A with 80 requests (60 RPM limit for unknown customers)
    const responsesA = await sendBurst(idA, 80);
    const allowedA = responsesA.filter((r) => r.statusCode === 200).length;

    // Customer B sends 10 — should all pass
    const responsesB = await sendBurst(idB, 10);
    const allowedB = responsesB.filter((r) => r.statusCode === 200).length;

    const passed = allowedA === 60 && allowedB === 10;
    const detail = `A: ${allowedA}/60 allowed | B: ${allowedB}/10 allowed`;
    updateResult(2, passed ? "pass" : "fail", detail);
    addLog(`Test 2: ${detail}`, passed ? "success" : "error");
  }

  async function runTest3() {
    setCurrentTest(3);
    updateResult(3, "running", "Setting simulated time to 02:30 UTC...");
    addLog("Test 3: Setting time to 02:30 UTC for Northwind batch window...");

    await setSimulatedTime("2026-03-15T02:30:00Z");
    // Small delay for time to propagate
    await new Promise((r) => setTimeout(r, 500));

    // Check audit to verify override
    const audit = await getAudit("northwind");
    const effectiveRpm = audit.body.currentEffective.rpm;

    if (effectiveRpm !== 1500) {
      updateResult(3, "fail", `Override not active! RPM=${effectiveRpm}`);
      addLog(`Test 3: Override not active! RPM=${effectiveRpm}`, "error");
      await resetSimulatedTime();
      return;
    }

    addLog("Test 3: Override active (1500 RPM). Sending 1550 requests...");
    const responses = await sendBurst("northwind", 1550);
    const allowed = responses.filter((r) => r.statusCode === 200).length;
    const rejected = responses.filter((r) => r.statusCode === 429).length;

    const passed = allowed === 1500 && rejected === 50;
    const detail = `RPM=1500 | Allowed: ${allowed}/1500, Rejected: ${rejected}/50`;
    updateResult(3, passed ? "pass" : "fail", detail);
    addLog(`Test 3: ${detail}`, passed ? "success" : "error");

    await resetSimulatedTime();
  }

  async function runTest4() {
    setCurrentTest(4);
    updateResult(4, "running", "Sending 90 requests across 3 nodes...");
    addLog("Test 4: Distributed correctness — 90 requests, expect 60 allowed...");

    const customerId = "harness-dist-" + Date.now();
    const responses = await sendBurst(customerId, 90);
    const allowed = responses.filter((r) => r.statusCode === 200).length;
    const rejected = responses.filter((r) => r.statusCode === 429).length;

    const passed = allowed === 60 && rejected === 30;
    const detail = `Allowed: ${allowed}/60 (not ${60 * 3}), Rejected: ${rejected}/30`;
    updateResult(4, passed ? "pass" : "fail", detail);
    addLog(`Test 4: ${detail}`, passed ? "success" : "error");
  }

  async function runTest5() {
    setCurrentTest(5);
    updateResult(5, "running", "Sending exactly 60, then 1 more...");
    addLog("Test 5: Boundary precision...");

    const customerId = "harness-bound-" + Date.now();
    const firstBatch = await sendBurst(customerId, 60);
    const firstAllowed = firstBatch.filter((r) => r.statusCode === 200).length;

    const extra = await sendBurst(customerId, 1);
    const extraRejected = extra[0].statusCode === 429;

    const passed = firstAllowed === 60 && extraRejected;
    const detail = `First 60: ${firstAllowed}/60 | Extra: ${extra[0].statusCode} (expect 429)`;
    updateResult(5, passed ? "pass" : "fail", detail);
    addLog(`Test 5: ${detail}`, passed ? "success" : "error");
  }

  async function runTest6() {
    setCurrentTest(6);
    updateResult(6, "running", "Checking Retry-After header...");
    addLog("Test 6: Retry-After header validation...");

    const customerId = "harness-retry-" + Date.now();
    await sendBurst(customerId, 60);

    const rejected = await sendBurst(customerId, 1);
    const res = rejected[0];

    const retryAfter = res.headers["retry-after"];
    const limit = res.headers["x-ratelimit-limit"];
    const remaining = res.headers["x-ratelimit-remaining"];
    const hasHeaders = retryAfter && limit && remaining === "0";

    const passed = res.statusCode === 429 && hasHeaders;
    const detail = `Status: ${res.statusCode} | Retry-After: ${retryAfter}s | Remaining: ${remaining}`;
    updateResult(6, passed ? "pass" : "fail", detail);
    addLog(`Test 6: ${detail}`, passed ? "success" : "error");
  }

  async function runTest7() {
    setCurrentTest(7);
    updateResult(7, "running", "Testing batch window transition...");
    addLog("Test 7: Northwind batch window end...");

    await setSimulatedTime("2026-03-15T03:59:00Z");
    await new Promise((r) => setTimeout(r, 500));

    const auditBefore = await getAudit("northwind");
    const rpmBefore = auditBefore.body.currentEffective.rpm;

    await setSimulatedTime("2026-03-15T04:01:00Z");
    await new Promise((r) => setTimeout(r, 500));

    const auditAfter = await getAudit("northwind");
    const rpmAfter = auditAfter.body.currentEffective.rpm;

    const passed = rpmBefore === 1500 && rpmAfter === 300;
    const detail = `Before: ${rpmBefore} RPM → After: ${rpmAfter} RPM`;
    updateResult(7, passed ? "pass" : "fail", detail);
    addLog(`Test 7: ${detail}`, passed ? "success" : "error");

    await resetSimulatedTime();
  }

  async function runTest8() {
    setCurrentTest(8);
    updateResult(8, "running", "Checking X-RateLimit-Source header...");
    addLog("Test 8: Redis source verification...");

    const customerId = "harness-source-" + Date.now();
    const responses = await sendBurst(customerId, 1);
    const source = responses[0].headers["x-ratelimit-source"];

    const passed = source === "redis";
    const detail = `X-RateLimit-Source: ${source}`;
    updateResult(8, passed ? "pass" : "fail", detail);
    addLog(`Test 8: ${detail}`, passed ? "success" : "error");
  }

  const passedCount = results.filter((r) => r.status === "pass").length;
  const failedCount = results.filter((r) => r.status === "fail").length;
  const totalDone = passedCount + failedCount;

  return (
    <div>
      <div className="card-header">
        <div>
          <h2 className="card-title">Harness Tests</h2>
          <p className="card-subtitle">Run automated tests against the rate limiter</p>
        </div>
        <button
          className="btn btn-primary"
          onClick={runAllTests}
          disabled={isRunning}
        >
          {isRunning ? (
            <>
              <span className="spinner"></span>
              Running...
            </>
          ) : (
            "▶ Run All Tests"
          )}
        </button>
      </div>

      {results.length > 0 && (
        <div className="stats-row" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}>
          <div className="stat-card">
            <div className="stat-value blue">{totalDone}/{TEST_DEFINITIONS.length}</div>
            <div className="stat-label">Completed</div>
          </div>
          <div className="stat-card">
            <div className="stat-value green">{passedCount}</div>
            <div className="stat-label">Passed</div>
          </div>
          <div className="stat-card">
            <div className="stat-value red">{failedCount}</div>
            <div className="stat-label">Failed</div>
          </div>
        </div>
      )}

      <table className="results-table">
        <thead>
          <tr>
            <th>#</th>
            <th>Test</th>
            <th>Status</th>
            <th>Details</th>
          </tr>
        </thead>
        <tbody>
          {TEST_DEFINITIONS.map((test) => {
            const result = results.find((r) => r.id === test.id);
            return (
              <tr key={test.id}>
                <td style={{ fontFamily: "'JetBrains Mono', monospace", color: "var(--text-muted)" }}>
                  {test.id}
                </td>
                <td>
                  <div>{test.name}</div>
                  <div style={{ fontSize: "0.75rem", color: "var(--text-muted)", marginTop: "2px" }}>
                    {test.description}
                  </div>
                </td>
                <td>
                  {result ? (
                    <span className={`status-badge ${result.status}`}>
                      {result.status === "running" && <span className="spinner" style={{ width: 10, height: 10, borderWidth: 1.5 }}></span>}
                      {result.status}
                    </span>
                  ) : (
                    <span className="status-badge pending">pending</span>
                  )}
                </td>
                <td style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "0.8rem", color: "var(--text-secondary)" }}>
                  {result ? result.detail : "—"}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      {logs.length > 0 && (
        <div style={{ marginTop: "var(--space-lg)" }}>
          <h3 className="card-title" style={{ marginBottom: "var(--space-md)", fontSize: "0.9rem" }}>
            Execution Log
          </h3>
          <div className="log-area">
            {logs.map((log, i) => (
              <div key={i} className={`log-line ${log.type}`}>
                <span style={{ color: "var(--text-muted)" }}>[{log.time}]</span> {log.message}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { sendBurst } from "../api";

/**
 * Manual Request Sender
 *
 * Pick a customer, set how many requests to send,
 * and see the results with a breakdown chart.
 */

const PRESET_CUSTOMERS = [
  { id: "northwind", label: "Northwind (Enterprise, 300 RPM)", rpm: 300 },
  { id: "acme-corp", label: "Acme Corp (Growth, 300 RPM)", rpm: 300 },
  { id: "small-biz", label: "Small Biz (Starter, 60 RPM)", rpm: 60 }
];

export default function ManualSender() {
  const [customerId, setCustomerId] = useState("small-biz");
  const [customCustomerId, setCustomCustomerId] = useState("");
  const [requestCount, setRequestCount] = useState(75);
  const [isRunning, setIsRunning] = useState(false);
  const [results, setResults] = useState(null);
  const [history, setHistory] = useState([]);

  async function handleSend() {
    const actualId = customerId === "custom" ? customCustomerId : customerId;
    if (!actualId) return;

    setIsRunning(true);
    setResults(null);

    const startTime = Date.now();
    const responses = await sendBurst(actualId, requestCount);
    const elapsed = Date.now() - startTime;

    const allowed = responses.filter((r) => r.statusCode === 200).length;
    const rejected = responses.filter((r) => r.statusCode === 429).length;
    const errors = responses.filter((r) => r.statusCode !== 200 && r.statusCode !== 429).length;

    // Get node distribution
    const nodeDistribution = {};
    responses.forEach((r) => {
      if (r.body && r.body.data && r.body.data.nodeId) {
        const nodeId = r.body.data.nodeId;
        nodeDistribution[nodeId] = (nodeDistribution[nodeId] || 0) + 1;
      }
    });

    // Get rate limit info from last successful response
    const lastOk = responses.find((r) => r.statusCode === 200);
    const rateLimit = lastOk ? lastOk.headers["x-ratelimit-limit"] : "?";
    const source = lastOk ? lastOk.headers["x-ratelimit-source"] : "?";

    const result = {
      customerId: actualId,
      totalSent: requestCount,
      allowed,
      rejected,
      errors,
      elapsed,
      rateLimit,
      source,
      nodeDistribution,
      timestamp: new Date().toISOString()
    };

    setResults(result);
    setHistory((prev) => [result, ...prev].slice(0, 10));
    setIsRunning(false);
  }

  return (
    <div>
      <div className="card-header">
        <div>
          <h2 className="card-title">Manual Request Sender</h2>
          <p className="card-subtitle">Send a burst of requests and see the results</p>
        </div>
      </div>

      <div className="form-row-3">
        <div className="form-group">
          <label className="form-label">Customer</label>
          <select
            className="form-select"
            value={customerId}
            onChange={(e) => setCustomerId(e.target.value)}
          >
            {PRESET_CUSTOMERS.map((c) => (
              <option key={c.id} value={c.id}>{c.label}</option>
            ))}
            <option value="custom">Custom ID...</option>
          </select>
        </div>

        {customerId === "custom" && (
          <div className="form-group">
            <label className="form-label">Custom ID</label>
            <input
              className="form-input"
              type="text"
              placeholder="my-customer-id"
              value={customCustomerId}
              onChange={(e) => setCustomCustomerId(e.target.value)}
            />
          </div>
        )}

        <div className="form-group">
          <label className="form-label">Number of Requests</label>
          <input
            className="form-input"
            type="number"
            min="1"
            max="5000"
            value={requestCount}
            onChange={(e) => setRequestCount(parseInt(e.target.value) || 1)}
          />
        </div>

        <div className="form-group" style={{ display: "flex", alignItems: "flex-end" }}>
          <button
            className="btn btn-primary"
            onClick={handleSend}
            disabled={isRunning}
            style={{ width: "100%" }}
          >
            {isRunning ? (
              <>
                <span className="spinner"></span>
                Sending {requestCount} requests...
              </>
            ) : (
              `Send ${requestCount} Requests`
            )}
          </button>
        </div>
      </div>

      {results && (
        <div style={{ marginTop: "var(--space-xl)" }}>
          <div className="stats-row">
            <div className="stat-card">
              <div className="stat-value blue">{results.totalSent}</div>
              <div className="stat-label">Total Sent</div>
            </div>
            <div className="stat-card">
              <div className="stat-value green">{results.allowed}</div>
              <div className="stat-label">Allowed (200)</div>
            </div>
            <div className="stat-card">
              <div className="stat-value red">{results.rejected}</div>
              <div className="stat-label">Rejected (429)</div>
            </div>
            <div className="stat-card">
              <div className="stat-value yellow">{results.elapsed}ms</div>
              <div className="stat-label">Duration</div>
            </div>
          </div>

          {/* Visual bar showing allowed vs rejected ratio */}
          <div style={{ marginBottom: "var(--space-lg)" }}>
            <div style={{ fontSize: "0.8rem", color: "var(--text-muted)", marginBottom: "var(--space-sm)" }}>
              Request Distribution
            </div>
            <div style={{
              display: "flex",
              height: "32px",
              borderRadius: "var(--radius-sm)",
              overflow: "hidden",
              border: "1px solid var(--border-color)"
            }}>
              {results.allowed > 0 && (
                <div style={{
                  width: `${(results.allowed / results.totalSent) * 100}%`,
                  background: "var(--accent-green)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "0.75rem",
                  fontWeight: 600,
                  color: "white",
                  transition: "width 0.5s ease"
                }}>
                  {results.allowed} OK
                </div>
              )}
              {results.rejected > 0 && (
                <div style={{
                  width: `${(results.rejected / results.totalSent) * 100}%`,
                  background: "var(--accent-red)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "0.75rem",
                  fontWeight: 600,
                  color: "white",
                  transition: "width 0.5s ease"
                }}>
                  {results.rejected} Rejected
                </div>
              )}
            </div>
          </div>

          {/* Node distribution */}
          {Object.keys(results.nodeDistribution).length > 0 && (
            <div style={{ marginBottom: "var(--space-lg)" }}>
              <div style={{ fontSize: "0.8rem", color: "var(--text-muted)", marginBottom: "var(--space-sm)" }}>
                Node Distribution (Round-Robin)
              </div>
              <div style={{ display: "flex", gap: "var(--space-md)" }}>
                {Object.entries(results.nodeDistribution).map(([node, count]) => (
                  <div key={node} className="stat-card" style={{ flex: 1, padding: "var(--space-sm) var(--space-md)" }}>
                    <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "1.2rem", fontWeight: 600, color: "var(--accent-blue)" }}>
                      {count}
                    </div>
                    <div style={{ fontSize: "0.7rem", color: "var(--text-muted)", textTransform: "uppercase" }}>
                      {node}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div style={{ fontSize: "0.8rem", color: "var(--text-muted)" }}>
            Rate Limit: {results.rateLimit} RPM | Source: {results.source}
          </div>
        </div>
      )}

      {/* History */}
      {history.length > 1 && (
        <div style={{ marginTop: "var(--space-xl)" }}>
          <h3 className="card-title" style={{ fontSize: "0.9rem", marginBottom: "var(--space-md)" }}>
            Recent Runs
          </h3>
          <table className="results-table">
            <thead>
              <tr>
                <th>Customer</th>
                <th>Sent</th>
                <th>Allowed</th>
                <th>Rejected</th>
                <th>Duration</th>
                <th>Time</th>
              </tr>
            </thead>
            <tbody>
              {history.map((h, i) => (
                <tr key={i}>
                  <td style={{ fontFamily: "'JetBrains Mono', monospace" }}>{h.customerId}</td>
                  <td>{h.totalSent}</td>
                  <td style={{ color: "var(--accent-green)" }}>{h.allowed}</td>
                  <td style={{ color: "var(--accent-red)" }}>{h.rejected}</td>
                  <td>{h.elapsed}ms</td>
                  <td style={{ color: "var(--text-muted)", fontSize: "0.8rem" }}>
                    {new Date(h.timestamp).toLocaleTimeString()}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { getAudit, checkHealth } from "../api";

/**
 * Customer Dashboard
 *
 * Shows real-time rate limit status for each customer.
 * Auto-refreshes every 5 seconds.
 */

const CUSTOMERS = ["northwind", "acme-corp", "small-biz"];

export default function CustomerDashboard() {
  const [customerData, setCustomerData] = useState({});
  const [healthData, setHealthData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  async function fetchData() {
    try {
      // Fetch health
      const health = await checkHealth();
      setHealthData(health.body);

      // Fetch audit for each customer
      const data = {};
      for (const id of CUSTOMERS) {
        const audit = await getAudit(id);
        data[id] = audit.body;
      }
      setCustomerData(data);
    } catch (err) {
      console.error("Failed to fetch dashboard data:", err);
    }
    setIsLoading(false);
  }

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, []);

  if (isLoading) {
    return (
      <div style={{ textAlign: "center", padding: "var(--space-2xl)" }}>
        <div className="spinner" style={{ width: 32, height: 32, margin: "0 auto", borderWidth: 3 }}></div>
        <p style={{ marginTop: "var(--space-md)", color: "var(--text-muted)" }}>Loading dashboard...</p>
      </div>
    );
  }

  return (
    <div>
      <div className="card-header">
        <div>
          <h2 className="card-title">Customer Status Dashboard</h2>
          <p className="card-subtitle">Real-time rate limit status per customer (auto-refreshes every 5s)</p>
        </div>
        <button className="btn btn-outline btn-sm" onClick={fetchData}>
          ↻ Refresh
        </button>
