        </div>
      </div>

      {/* Custom time input */}
      <div className="form-row">
        <div className="form-group">
          <label className="form-label">Custom Time (ISO 8601)</label>
          <input
            className="form-input"
            type="datetime-local"
            value={customTime}
            onChange={(e) => setCustomTime(e.target.value)}
