        }}>
          {/* Batch window highlight */}
          <div style={{
            position: "absolute",
            left: `${(2 / 24) * 100}%`,
            width: `${(2 / 24) * 100}%`,
            height: "100%",
            background: "var(--accent-yellow-glow)",
            borderLeft: "2px solid var(--accent-yellow)",
            borderRight: "2px solid var(--accent-yellow)"
          }}>
            <div style={{
              position: "absolute",
              top: "4px",
