 */

const TABS = [
  { id: "harness", label: "🧪 Harness Tests" },
  { id: "sender", label: "🚀 Manual Sender" },
  { id: "dashboard", label: "📊 Dashboard" },
  { id: "time", label: "⏱ Time Sim" },
